    function testRegression_property() public {
        address vader = address(0x1);
        address usdv = address(0x2);
        address vault = address(0x3);
        c.init(vader, usdv, vault);

        c.newGrantProposal(address(0x4), 100);
        c.newGrantProposal(address(0x5), 200);

        bool ok;
        try c.cancelProposal(1, 2) { ok = true; } catch { ok = false; }

        assertTrue(c.USDV() != address(0));
    }
